        project.defaultTaskPriority = updated.defaultTaskPriority;
      } catch (error) {
        defaultPriority.value = previous;
        showError(error.message);
      }
    });
    const form = element('form', { className: 'create-form' });
    const label = element('label', { text: 'Task title' });
